schemas.content:
section readLines: ImmaterialLines
{
  scope.forNumberOfLines: 2;
  recordSeparator: ';';
}

section sectionName: DelimitedWithHeadings
{
  scope.untilEof;
  recordSeparator: ';';
  delimiter: '::';
  quoteChar: '\'';
  escapingChar: '\'';
  nullString: 'null';
  mayContainBlankLines;

  Record
  {
    HEADING1: STRING;
    HEADING2: INTEGER(optional);
    HEADING3: BOOLEAN(trueString='Y', falseString='N', optional);
    'My Fourth Heading': DECIMAL(optional);
    HEADING5: DATE(format='MM-DD-EE');
    HEADING6: DATETIME(format='MM-DD-EE');
  }
}

section sectionName2: DelimitedWithoutHeadings
{
  scope.forNumberOfLines: 1;
  recordSeparator: '\n';
  delimiter: ',';
  quoteChar: '\'';
  escapingChar: '\'';
  nullString: 'None';

  Record
  {
    A {1}: STRING;
    B {2}: INTEGER(format='#,##0', optional);
    C {3}: DECIMAL(format='#,##0.0#', optional);
    D {4}: BOOLEAN(optional);
    E {5}: DATE(format='MM-DD-EE');
    F {6}: DATETIME(format='MM-DD-EE');
  }
}
